<?php
declare(strict_types=1);
if(empty($wams['authorized'])){http_response_code(403);exit('WAMS authorization required.');}
$c=$wams['config'];function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$rows=[];$headers=[];$error='';$meta=['bytes'=>0,'fetchedAt'=>gmdate('c')];
try{$url=(string)($c['remoteUrl']??'');if(!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Ungültige Remote-CSV-URL.');$ctx=stream_context_create(['http'=>['timeout'=>max(2,min(60,(int)($c['timeoutSeconds']??20))),'ignore_errors'=>true,'header'=>"Accept: text/csv,text/plain;q=0.9,*/*;q=0.1\r\nUser-Agent: WAMS-CSV-Reporting/1.3\r\n"]]);$raw=@file_get_contents($url,false,$ctx);if($raw===false)throw new RuntimeException('Remote-Daten sind nicht erreichbar. Eventuell wird DNS blockiert. Versuche, sofern beim Zielsystem zulässig, die IP-Adresse statt des Hostnamens.');$meta['bytes']=strlen($raw);$f=fopen('php://temp','r+');fwrite($f,$raw);rewind($f);$delimiter=(string)($c['delimiter']??',');if($delimiter==='\\t')$delimiter="\t";while(($r=fgetcsv($f,0,$delimiter))!==false)$rows[]=$r;fclose($f);if(($c['hasHeader']??true)&&$rows)$headers=array_map(fn($v)=>trim((string)$v),array_shift($rows));$width=max(array_map('count',$rows?:[[]]));if(!$headers)for($i=0;$i<$width;$i++)$headers[]='Spalte '.($i+1);foreach($rows as &$r)$r=array_pad($r,count($headers),'');unset($r);}catch(Throwable $ex){$error=$ex->getMessage();}
$renames=is_array($c['columnRenames']??null)?$c['columnRenames']:[];$links=is_array($c['columnLinks']??null)?$c['columnLinks']:[];$show=is_array($c['showColumns']??null)?array_values(array_filter($c['showColumns'])):[];
if($show){$idx=[];foreach($show as $name){$i=array_search($name,$headers,true);if($i!==false)$idx[]=$i;}if($idx){$headers=array_map(fn($i)=>$headers[$i],$idx);$rows=array_map(fn($r)=>array_map(fn($i)=>$r[$i]??'',$idx),$rows);}}
$displayHeaders=array_map(fn($h)=>$renames[$h]??$h,$headers);
$refresh=max(0,(int)($c['refreshSeconds']??0));
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($c['title']??'CSV Reporting')?></title><?php if($refresh):?><meta http-equiv="refresh" content="<?=$refresh?>"><?php endif?><link rel="stylesheet" href="<?=e($wams['styleUrl'])?>"></head><body><main class="csv"><div class="shell"><header class="report-head"><div><h1><?=e($c['heading']??'CSV Reporting')?></h1><p>Live-Daten · <?=count($rows)?> Zeilen · <?=number_format($meta['bytes']/1024,1,',','.')?> KiB · nicht lokal gespeichert</p></div><?php if($wams['canManage']):?><a class="manage" href="<?=e($wams['manageUrl'])?>">Verwalten</a><?php endif?></header><?php if($error):?><div class="err"><?=e($error)?></div><?php else:?><section class="box"><div class="tools"><input id="globalFilter" type="search" placeholder="Alle Spalten durchsuchen"><select id="pageSize"><option>25</option><option selected>50</option><option>100</option><option>250</option></select><button id="clearFilters">Filter löschen</button><span id="resultCount"></span></div><div class="column-filters"><?php foreach($displayHeaders as $i=>$h):?><label><?=e($h)?><input data-column="<?=$i?>" placeholder="Filtern"></label><?php endforeach?></div><div class="scroll"><table id="reportTable"><thead><tr><?php foreach($displayHeaders as $i=>$h):?><th data-sort="<?=$i?>"><?=e($h)?> <span>↕</span></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $ci=>$v):?><td><?php $original=$headers[$ci]??'';if(isset($links[$original])):$href=str_replace('{value}',rawurlencode((string)$v),(string)$links[$original]);?><a href="<?=e($href)?>" target="_blank" rel="noopener"><?=e($v)?></a><?php else:?><?=e($v)?><?php endif?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div><footer class="pager"><button id="prev">Zurück</button><span id="pageInfo"></span><button id="next">Weiter</button></footer></section><?php endif?></div></main><script src="<?=e($wams['scriptUrl'])?>"></script></body></html>
